#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
mkdir -p constant/geometry
cp -f \
"$FOAM_TUTORIALS"/resources/geometry/NACA0012.obj.gz \
constant/geometry
restore0Dir
runApplication blockMesh
runApplication transformPoints -scale '(1 0 1)'
runApplication extrudeMesh
#------------------------------------------------------------------------------
cd 切换当前工作目录。
mkdir 创建一个或多个目录。
cp 复制文件或目录。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
transformPoints 平移、旋转或缩放网格坐标，可同步旋转向量与张量场。
extrudeMesh 按指定方向和层数挤出表面或网格边界，生成体网格。
